brief:
Add accounts to the starter app. A sign-up page at /signup asks for an email, a password of at least 8 characters and the password repeated, with a validation message per field and a message when the two passwords differ; a valid sign-up signs the user in and goes to /account. An administration page at /admin is only for signed-in users with the admin role: anonymous visitors are sent to the login page and come back after signing in, signed-in users without the role get the permission-denied page naming the missing role. In the development demo, an email starting with admin@ has the admin role.

Start from the auth recipe in bench/recipes/auth (Auth pages + role guard). It already passes brain check, brain doctor and brain test in a fresh brain_new app. Its files are below, each with its path relative to the app root: after brain_new, write them as they are (they replace the scaffold files with the same path), then adapt names, routes and texts to the brief, keeping the structure and the tests passing.
Recipe notes: The demo provider exists only while DEMO_PASSWORD is set ([development] in .brain_env); replace check() and register() with a real provider. In the demo an email starting with admin@ gets the admin role.

=== server/auth.jsbrain ===
<meta server>
// Demo authentication. DEMO_PASSWORD exists only in the [development] block of .brain_env, so a deployed app has
// no demo login: replace check() and register() with your real provider (database lookup, OAuth…).
// Demo roles: an email starting with admin@ is an admin, everyone else a member.
const configured = () => Boolean(process.env.DEMO_PASSWORD)
const roleOf = (email) => (email.startsWith('admin@') ? 'admin' : 'member')

export default {
  configured,
  check: (email, password) => configured() && password === process.env.DEMO_PASSWORD ? { email, role: roleOf(email) } : null,
  // the demo keeps no accounts: a valid sign-up signs the user in; a real provider stores the account here
  register: (email) => configured() ? { email, role: roleOf(email) } : null,
}

=== views/signup.brain ===
<meta seo title="Create an account" description="Create an account with your email and a password of at least 8 characters. In development the demo provider signs you in at once.">

<script>
  import auth from '../server/auth.jsbrain'
  import session from '../channels/session.jsbrain'

  export async function load() {
    return { configured: auth.configured() }
  }
  server: async function signup(ctx, v) {
    if (typeof v.email !== 'string' || !v.email.includes('@')) throw { errors: { email: 'Enter a valid email' } }
    if (typeof v.password !== 'string' || v.password.length < 8) throw { errors: { password: 'Use at least 8 characters' } }
    const user = auth.register(v.email)
    if (!user) throw { errors: { email: 'Sign-up is not available' } }
    ctx.session.set(user)
    return { user }
  }
  let f = form({ email: 'email!', password: 'str!', confirm: 'str!' }, {
    submit: async (v) => {
      if (v.password.length < 8) throw { errors: { password: 'Use at least 8 characters' } }
      if (v.password !== v.confirm) throw { errors: { confirm: 'The passwords do not match' } }
      const r = await signup({ email: v.email, password: v.password })
      session.user = r.user
      navigate('/account')
    },
  })
</script>

<main class="page">
  <h1>Create an account</h1>
  {#if props.configured}
    <form on:submit={f.submit}>
      <Input label="Email" type="email" autocomplete="email" bind:value={f.v.email} error={f.err.email} />
      <Input label="Password" type="password" autocomplete="new-password" help="At least 8 characters" bind:value={f.v.password} error={f.err.password} />
      <Input label="Repeat the password" type="password" autocomplete="new-password" bind:value={f.v.confirm} error={f.err.confirm} />
      {#if f.error}<p role="alert" class="err">{f.error}</p>{/if}
      <Button type="submit" busy={f.busy}>Create account</Button>
    </form>
    <p>Already have an account? <a href="/login">Sign in</a></p>
  {:else}
    <p role="status">Sign-up is not configured. Connect a real provider in server/auth.jsbrain (the demo exists only in development).</p>
  {/if}
</main>

<style>
